function generateOrderId() {
  return "AEH" + Date.now().toString().slice(-6);
}

export default function App() {
  const [page, setPage] = useState(PAGES.HOME);
  const [orderType, setOrderType] = useState("ebook");
  const [form, setForm] = useState({ name: "", email: "", phone: "", address: "" });
  const [txnId, setTxnId] = useState("");
  const [currentOrder, setCurrentOrder] = useState(null);
  const [trackId, setTrackId] = useState("");
  const [trackedOrder, setTrackedOrder] = useState(null);
  const [trackError, setTrackError] = useState(false);
  const [orders, setOrders] = useState([]);

  useEffect(() => { loadOrders(); }, []);

  const loadOrders = async () => {
    try {
      const r = await window.storage.get("aeh-orders");
      if (r) setOrders(JSON.parse(r.value));
    } catch { setOrders([]); }
  };

  const saveOrders = async (newOrders) => {
    try {
      await window.storage.set("aeh-orders", JSON.stringify(newOrders));
    } catch (e) {}
  };

  const handleOrderSubmit = () => {
    if (!form.name || !form.email || !form.phone) return;
    if (orderType === "paperback" && !form.address) return;
    setPage(PAGES.PAYMENT);
  };

  const handlePaymentConfirm = () => {
    if (!txnId.trim()) return;
    const order = {
      id: generateOrderId(),
      type: orderType,
      name: form.name,
      email: form.email,
      phone: form.phone,
      address: form.address,
      txnId: txnId,
      amount: orderType === "ebook" ? EBOOK_PRICE : PAPERBACK_PRICE,
      status: 0,
      createdAt: new Date().toLocaleString("en-IN"),
    };
    const newOrders = [...orders, order];
    setOrders(newOrders);
    saveOrders(newOrders);
    setCurrentOrder(order);
    setPage(PAGES.CONFIRM);
  };

  const handleTrack = () => {
    const found = orders.find(o => o.id.toLowerCase() === trackId.trim().toLowerCase());
    if (found) { setTrackedOrder(found); setTrackError(false); }
    else { setTrackedOrder(null); setTrackError(true); }
  };

  const getStatusBadge = (status) => {
    const labels = ["Pending", "Confirmed", "Printing", "Dispatched", "Delivered"];
    const classes = ["badge-pending", "badge-confirmed", "badge-printing", "badge-dispatched", "badge-delivered"];
    return <span className={`track-status-badge ${classes[status]}`}>{labels[status]}</span>;
  };

  return (
    <>
      <style>{styles}</style>
      <div className="app">
        <div className="cloud cloud-1" />
        <div className="cloud cloud-2" />
        <div className="cloud cloud-3" />

        <nav className="nav">
          <span className="nav-brand" onClick={() => setPage(PAGES.HOME)} style={{cursor:"pointer"}}>Arz-e-Haal</span>
          <button className="nav-track-btn" onClick={() => setPage(PAGES.TRACK)}>📦 Track Order</button>
        </nav>

        {/* HOME */}
        {page === PAGES.HOME && (
          <div className="page">
            <div className="hero">
              <div className="book-cover">
                <div className="spiral">
                  {[...Array(14)].map((_, i) => <div key={i} className="spiral-ring" />)}
                </div>
                <div className="book-clouds" />
                <div className="book-title">ARZ-E-<br/>HAAL</div>
                <div className="book-subtitle">A Poetry Collection</div>
              </div>
              <div className="hero-title">Arz-e-Haal</div>
              <div className="hero-subtitle">A Poetry Collection</div>
              <div className="hero-quote">"Jo dil mein tha, woh kagaz par aa gaya..."</div>
            </div>

            <div className="price-cards">
              <div className="price-card">
                <div className="price-tag">Digital</div>
                <div className="price-type">📱 Ebook</div>
                <div className="price-amount">₹99</div>
                <div className="price-note">Instant PDF Download</div>
              </div>
              <div className="price-card featured">
                <div className="price-tag">Physical</div>
                <div className="price-type">📖 Paperback</div>
                <div className="price-amount">₹299</div>
                <div className="price-note">Spiral Bound · Home Delivery</div>
              </div>
            </div>

            <button className="order-btn" onClick={() => setPage(PAGES.ORDER)}>
              Order Your Copy ✨
            </button>


          </div>
        )}

        {/* ORDER FORM */}
        {page === PAGES.ORDER && (
          <div className="page form-page">
            <button className="back-btn" onClick={() => setPage(PAGES.HOME)}>← Back</button>
            <div className="form-header">
              <div className="form-title">Place Your Order</div>
              <div className="form-subtitle">Fill in your details</div>
            </div>

            <div className="type-selector">
              <div className={`type-btn ${orderType === "ebook" ? "active" : ""}`} onClick={() => setOrderType("ebook")}>
                <div className="type-btn-title">📱 Ebook</div>
                <div className="type-btn-price">₹99</div>
                <div className="type-btn-note">PDF Download</div>
              </div>
              <div className={`type-btn ${orderType === "paperback" ? "active" : ""}`} onClick={() => setOrderType("paperback")}>
                <div className="type-btn-title">📖 Paperback</div>
                <div className="type-btn-price">₹299</div>
                <div className="type-btn-note">Spiral Bound</div>
              </div>
            </div>

            <div className="input-group">
              <label className="input-label">Full Name *</label>
              <input className="input-field" placeholder="Your name" value={form.name} onChange={e => setForm({...form, name: e.target.value})} />
            </div>
            <div className="input-group">
              <label className="input-label">Email *</label>
              <input className="input-field" placeholder="your@email.com" type="email" value={form.email} onChange={e => setForm({...form, email: e.target.value})} />
            </div>
            <div className="input-group">
              <label className="input-label">Phone *</label>
              <input className="input-field" placeholder="10 digit number" type="tel" value={form.phone} onChange={e => setForm({...form, phone: e.target.value})} />
            </div>
            {orderType === "paperback" && (
              <div className="input-group">
                <label className="input-label">Delivery Address *</label>
                <textarea className="input-field" placeholder="Full address with pincode" rows={3} value={form.address} onChange={e => setForm({...form, address: e.target.value})} style={{resize:"none"}} />
              </div>
            )}

            <button
              className="submit-btn"
              onClick={handleOrderSubmit}
              disabled={!form.name || !form.email || !form.phone || (orderType === "paperback" && !form.address)}
            >
              Proceed to Payment →
            </button>
          </div>
        )}

        {/* PAYMENT */}
        {page === PAGES.PAYMENT && (
          <div className="page payment-page">
            <button className="back-btn" onClick={() => setPage(PAGES.ORDER)}>← Back</button>

            <div className="payment-card">
              <div className="payment-title">Complete Payment</div>
              <div style={{fontSize:13, color:"#9a8ab0"}}>{orderType === "ebook" ? "Ebook · PDF Download" : "Paperback · Spiral Bound"}</div>
              <div className="payment-amount">₹{orderType === "ebook" ? EBOOK_PRICE : PAPERBACK_PRICE}</div>

              <div className="upi-box">
                <div className="upi-label">Pay via UPI</div>
                <div className="upi-id">{UPI_ID}</div>
                <div className="qr-placeholder">
                  <img
                    src="data:image/jpeg;base64,"
                    alt="UPI QR Code"
                    style={{
                      width: "100%",
                      height: "100%",
                      objectFit: "cover",
                      objectPosition: "50% 38%",
                      borderRadius: "10px",
                      display: "block"
                    }}
                  />
                </div>
                <div style={{fontSize:12, color:"#9a8ab0"}}>Or search UPI ID in any payment app</div>
              </div>

              <div className="steps-list">
                {["Open GPay / PhonePe / Paytm", `Pay ₹${orderType === "ebook" ? EBOOK_PRICE : PAPERBACK_PRICE} to the UPI ID above`, "Copy your Transaction ID (UTR)", "Paste it below and confirm"].map((s, i) => (
                  <div key={i} className="step-item">
                    <div className="step-num">{i + 1}</div>
                    <div>{s}</div>
                  </div>
                ))}
              </div>
            </div>

            <div className="input-group">
              <label className="input-label">Transaction ID / UTR Number *</label>
              <input className="input-field" placeholder="Enter your transaction ID" value={txnId} onChange={e => setTxnId(e.target.value)} />
            </div>
            <div className="alert alert-info">
              ℹ️ Your order will be confirmed within 2 hours after payment verification.
            </div>
            <button className="submit-btn" onClick={handlePaymentConfirm} disabled={!txnId.trim()}>
              Confirm Order ✓
            </button>
          </div>
        )}

        {/* CONFIRMATION */}
        {page === PAGES.CONFIRM && currentOrder && (
          <div className="page confirm-page">
            <div className="success-icon">🎉</div>
            <div className="confirm-title">Order Placed!</div>
            <div className="confirm-subtitle">
              {currentOrder.type === "ebook"
                ? "Your ebook download will be available after payment verification"
                : "Your paperback will be delivered soon!"}
            </div>

            <div className="order-id-box">
              <div className="order-id-label">Your Order ID</div>
              <div className="order-id-val">{currentOrder.id}</div>
              <div style={{fontSize:11, color:"#9a8ab0", marginTop:4}}>Save this to track your order</div>
            </div>

            {currentOrder.type === "ebook" ? (
              <div className="download-card">
                <div style={{fontFamily:"'Cormorant Garamond',serif", fontSize:22, color:"#3a2f6a", marginBottom:8}}>📖 Your Ebook</div>
                <div style={{fontSize:13, color:"#9a8ab0", marginBottom:8}}>Arz-e-Haal — A Poetry Collection</div>
                <div className="alert alert-info">⏳ Download link will be sent to {currentOrder.email} within 2 hours after payment verification.</div>
                <div style={{fontSize:12, color:"#9a8ab0"}}>Or DM on Instagram with your Order ID to get instant access.</div>
              </div>
            ) : (
              <div className="download-card">
                <div style={{fontFamily:"'Cormorant Garamond',serif", fontSize:22, color:"#3a2f6a", marginBottom:8}}>📦 Paperback Order</div>
                <div style={{fontSize:13, color:"#9a8ab0", marginBottom:12}}>Delivering to: {currentOrder.address}</div>
                <div className="alert alert-info">⏳ Order will be confirmed within 2 hours. You can track using your Order ID.</div>
              </div>
            )}

            <button className="download-btn" onClick={() => { setPage(PAGES.HOME); setForm({name:"",email:"",phone:"",address:""}); setTxnId(""); }}>
              Back to Home
            </button>
            <button className="download-btn" style={{marginTop:12, background:"rgba(123,94,167,0.15)", color:"#7b5ea7"}}
              onClick={() => { setTrackId(currentOrder.id); setPage(PAGES.TRACK); setTimeout(handleTrack, 100); }}>
              Track This Order
            </button>
          </div>
        )}

        {/* TRACKING */}
        {page === PAGES.TRACK && (
          <div className="page track-page">
            <button className="back-btn" onClick={() => setPage(PAGES.HOME)}>← Back</button>
            <div className="form-header" style={{marginBottom:24}}>
              <div className="form-title">Track Your Order</div>
              <div className="form-subtitle">Enter your order ID</div>
            </div>

            <div className="track-input-row">
              <input className="input-field" placeholder="e.g. AEH123456" value={trackId} onChange={e => setTrackId(e.target.value)} />
              <button className="track-btn" onClick={handleTrack}>Track</button>
            </div>

            {trackError && <div className="not-found">No order found with this ID.<br/>Please check and try again.</div>}

            {trackedOrder && (
              <div className="track-card">
                <div className="track-header">
                  <div>
                    <div className="track-type">{trackedOrder.type === "ebook" ? "📱 Ebook" : "📖 Paperback"}</div>
                    <div style={{fontSize:12, color:"#9a8ab0"}}>{trackedOrder.id} · ₹{trackedOrder.amount}</div>
                  </div>
                  {getStatusBadge(trackedOrder.status)}
                </div>

                {trackedOrder.type === "paperback" ? (
                  <div className="progress-steps">
                    {STATUS_STEPS.map((step, i) => {
                      const isDone = i < trackedOrder.status;
                      const isActive = i === trackedOrder.status;
                      const isLast = i === STATUS_STEPS.length - 1;
                      return (
                        <div key={i} className="progress-step">
                          <div className="step-line-col">
                            <div className={`step-dot ${isDone ? "done" : isActive ? "active" : ""}`}>
                              {isDone ? "✓" : ""}
                            </div>
                            {!isLast && <div className={`step-line ${isDone ? "done" : ""}`} />}
                          </div>
                          <div className="step-content">
                            <div className={`step-label ${isActive ? "active" : isDone ? "" : "pending"}`}>{step}</div>
                            {isDone && <div className="step-time">Completed</div>}
                            {isActive && <div className="step-time" style={{color:"#7b5ea7"}}>In Progress</div>}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                ) : (
                  <div>
                    <div className="alert alert-info">
                      📧 Payment under verification. Ebook will be sent to <strong>{trackedOrder.email}</strong> within 2 hours.
                    </div>
                    <div style={{fontSize:13, color:"#9a8ab0", textAlign:"center"}}>For instant access, DM on Instagram with Order ID: <strong>{trackedOrder.id}</strong></div>
                  </div>
                )}

                <div style={{marginTop:16, fontSize:12, color:"#bbb", textAlign:"center"}}>
                  Ordered on {trackedOrder.createdAt} · Transaction: {trackedOrder.txnId}
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </>
  );
}
